func (bb *BatchBuffer) resolveSchemaAdapter(record *shadow.UpsertRecord, db *gorm.DB) *serviceshadow.SchemaAdapter {
	if db == nil {
		return bb.schemaAdapter
	}
	cacheKey := "legacy"
	if record != nil {
		cacheKey = strings.TrimSpace(record.ConnectionRole) + ":" + strings.TrimSpace(record.ConnectionKey)
		if cacheKey == ":" || cacheKey == "" {
			cacheKey = "legacy"
		}
	}
	if cached, ok := bb.adapters.Load(cacheKey); ok {
		return cached.(*serviceshadow.SchemaAdapter)
	}
	adapter := serviceshadow.NewSchemaAdapter(db, bb.logger)
	bb.adapters.Store(cacheKey, adapter)
	return adapter
}

